create function test.review(v integer default 1,e uuid default '71000000-0000-0000-0000-000000000001',a text default 'awak',h integer default 0)
returns jsonb language sql as $$ select public.review_word(e,'30000000-0000-0000-0000-000000000001','meaning',a,v,h,30) $$;
set role anon;
select test.denied('select test.review()','anonymous review denied');
select test.denied($$select public.test_out_unit(gen_random_uuid(),'rpc-unit',1,'[]',30)$$,'anonymous test-out denied');
reset role;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select test.denied('select test.review()','nonowner review denied');
select test.denied($$select public.test_out_unit(gen_random_uuid(),'rpc-unit',1,'[]',30)$$,'nonowner test-out denied');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select test.denied($$select private.award_activity(auth.uid(),current_date)$$,'client cannot award arbitrary streak date');
select test.denied($$select private.initialize_reviews(auth.uid(),'20000000-0000-0000-0000-000000000001')$$,'client cannot initialize schedules');
select test.denied($$select private.complete_lesson_v3(gen_random_uuid(),'rpc-one',1,'[]',1)$$,'old completion helper no public escape');
select test.denied('select test.review(h=>3)','hints bounded','22023');
select test.denied('select test.review(v=>99)','schedule version conflict','22023');
select test.ok((test.review()->'schedule'->>'interval_days')::int=1,'first SM2 interval one day');
select test.ok((test.review()->'schedule'->>'ease_factor')::numeric=2.6,'correct no-hint SM2 ease update');
select test.ok((test.review()->>'grade')::int=5,'grade derived from answer');
select test.ok((select count(*) from public.study_sessions where client_event_id='71000000-0000-0000-0000-000000000001')=1,'review retry exactly once');
select test.denied('select test.review(a=>''wrong'')','review retry payload conflict','22023');
select test.denied($$select test.review(v=>2,e=>'71000000-0000-0000-0000-000000000002')$$,'early review rejected','22023');
reset role;
update public.review_schedule set due_at=now()-interval '1 minute' where word_id='30000000-0000-0000-0000-000000000001';
set role authenticated;
select test.ok((test.review(v=>2,e=>'71000000-0000-0000-0000-000000000002')->'schedule'->>'interval_days')::int=6,'second SM2 interval six days');
reset role;
update public.review_schedule set due_at=now()-interval '1 minute' where word_id='30000000-0000-0000-0000-000000000001';
set role authenticated;
select test.ok((test.review(v=>3,e=>'71000000-0000-0000-0000-000000000003')->'schedule'->>'interval_days')::int=16,'later SM2 interval rounds previous ease times interval');
reset role;
update public.review_schedule set due_at=now()-interval '1 minute',ease_factor=1.3 where word_id='30000000-0000-0000-0000-000000000001';
set role authenticated;
select test.ok((test.review(v=>4,e=>'71000000-0000-0000-0000-000000000004',a=>'wrong')->'schedule'->>'repetitions')::int=0,'lapse resets repetitions');
select test.ok((test.review(v=>4,e=>'71000000-0000-0000-0000-000000000004',a=>'wrong')->'schedule'->>'ease_factor')::numeric=1.3,'SM2 ease floor preserved');
select test.ok((test.review(v=>4,e=>'71000000-0000-0000-0000-000000000004',a=>'wrong')->'schedule'->>'interval_days')::int=1,'lapse due next day');
select test.ok((test.review(v=>4,e=>'71000000-0000-0000-0000-000000000004',a=>'wrong')->>'xp_awarded')::int=0,'wrong review earns no XP');
select test.ok(exists(select 1 from public.user_achievements ua join public.achievements a on a.id=ua.achievement_id where a.code='first-review'),'review badge awarded canonically');
reset role;
begin;
update public.streak_state set current_days=0,longest_days=0,last_active_date=null,freeze_balance=1,active_days=0;
select private.award_activity('00000000-0000-0000-0000-000000000001','2025-01-01');
select private.award_activity('00000000-0000-0000-0000-000000000001','2025-01-01');
select test.ok(current_days=1 and active_days=1 and freeze_balance=1,'same-day streak activity counted once') from public.streak_state;
select private.award_activity('00000000-0000-0000-0000-000000000001','2025-01-03');
select private.award_activity('00000000-0000-0000-0000-000000000001','2025-01-03');
select test.ok(current_days=3 and active_days=2 and freeze_balance=0,'one missing day consumes one freeze exactly once') from public.streak_state;
select test.ok((select freeze_used from public.daily_activity where local_date='2025-01-02'),'frozen missing date recorded');
select private.award_activity('00000000-0000-0000-0000-000000000001','2025-01-06');
select test.ok(current_days=1 and longest_days=3,'long gap resets current but preserves longest') from public.streak_state;
update public.streak_state set active_days=6;
select private.award_activity('00000000-0000-0000-0000-000000000001','2025-01-07');
select test.ok(active_days=7 and freeze_balance=1,'seven active days replenish one freeze') from public.streak_state;
update public.streak_state set active_days=13,freeze_balance=2;
select private.award_activity('00000000-0000-0000-0000-000000000001','2025-01-08');
select test.ok(freeze_balance=2,'freeze balance capped at two') from public.streak_state;
select test.ok(('2026-01-01 15:59:59+00'::timestamptz at time zone 'Asia/Kuala_Lumpur')::date='2026-01-01' and ('2026-01-01 16:00:00+00'::timestamptz at time zone 'Asia/Kuala_Lumpur')::date='2026-01-02','Malaysia midnight boundary');
rollback;
-- The Unit0 fixture has a published later lesson without completed progress.
set role authenticated;
select test.denied($$select public.test_out_unit(gen_random_uuid(),'published',1,'[{"lesson_slug":"rpc-two","item_id":"three","answer":"awak"}]',30)$$,'Unit0 cannot be tested out','22023');
select test.denied($$select public.test_out_unit(gen_random_uuid(),'rpc-unit',1,'[{"lesson_slug":"rpc-one","item_id":"one","answer":"mā"}]',30)$$,'missing full-unit answers rejected','22023');
reset role;
update private.lesson_items set needs_review=false where lesson_id='62000000-0000-0000-0000-000000000001';
-- Make a fresh later unit for a genuine test-out; previous progression is untouched.
insert into public.units(id,slug,position,title_ms,title_en,content_version,published,prerequisite_unit_id)
values('72000000-0000-0000-0000-000000000001','testout',12,'Ujian','Test',1,true,'10000000-0000-0000-0000-000000000001');
insert into public.lessons(id,unit_id,position,title_ms,title_en,kind,duration_seconds,content_path,content_version,published,slug)
values('73000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000001',0,'Ujian','Test','vocabulary',60,'test/out',1,true,'testout-one');
insert into private.lesson_items select '73000000-0000-0000-0000-000000000001',1,'q-'||i,'yes',false from generate_series(1,10) i;
create function test.testout(right_answers integer,e uuid) returns jsonb language sql as $$
select public.test_out_unit(e,'testout',1,(select jsonb_agg(jsonb_build_object('lesson_slug','testout-one','item_id','q-'||i,'answer',case when i<=right_answers then 'yes' else 'no' end)) from generate_series(1,10)i),60) $$;
set role authenticated;
select test.ok(not (test.testout(8,'74000000-0000-0000-0000-000000000001')->>'passed')::boolean,'test-out 80percent does not pass');
select test.ok(not exists(select 1 from public.user_progress where lesson_id='73000000-0000-0000-0000-000000000001'),'failed test-out never unlocks progress');
select test.ok((test.testout(9,'74000000-0000-0000-0000-000000000002')->>'passed')::boolean,'test-out 90percent passes');
select test.ok(exists(select 1 from public.user_progress where lesson_id='73000000-0000-0000-0000-000000000001' and status='completed'),'test-out marks unit lesson completed');
select test.ok((test.testout(9,'74000000-0000-0000-0000-000000000002')->>'xp_awarded')::int=90,'test-out replay returns original reward');
select test.ok((select count(*) from public.study_sessions where client_event_id='74000000-0000-0000-0000-000000000002')=1,'test-out replay no duplicate session');
select test.denied($$select test.testout(10,'74000000-0000-0000-0000-000000000002')$$,'test-out replay conflict rejected','22023');
select test.denied($$select public.test_out_unit(gen_random_uuid(),'testout',1,'[{"lesson_slug":"testout-one","item_id":"q-1","answer":"yes","score":1}]',30)$$,'forged test-out score rejected','22023');
reset role;
